def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    from collections import deque
    from fractions import Fraction

    jump = dict(jumps)
    destination = list(range(n + 1))

    for cell in range(1, n):
        current = cell
        while current in jump:
            current = jump[current]
        destination[cell] = current

    transitions = [[] for _ in range(n + 1)]
    reverse = [[] for _ in range(n + 1)]

    for cell in range(n):
        for roll in range(1, m + 1):
            landed = cell + roll
            if landed > n:
                landed = 2 * n - landed
            landed = destination[landed]
            transitions[cell].append(landed)
            reverse[landed].append(cell)

    reachable = {0}
    queue = deque([0])
    while queue:
        cell = queue.popleft()
        if cell == n:
            continue
        for nxt in transitions[cell]:
            if nxt not in reachable:
                reachable.add(nxt)
                queue.append(nxt)

    can_finish = {n}
    queue = deque([n])
    while queue:
        cell = queue.popleft()
        for prev in reverse[cell]:
            if prev not in can_finish:
                can_finish.add(prev)
                queue.append(prev)

    if not reachable <= can_finish:
        return None

    states = sorted(reachable - {n})
    index = {cell: i for i, cell in enumerate(states)}
    size = len(states)

    # Each row represents m * E[cell] - sum(E[next]) = m.
    matrix = [[0] * (size + 1) for _ in range(size)]
    for cell in states:
        i = index[cell]
        matrix[i][i] = m
        matrix[i][size] = m
        for nxt in transitions[cell]:
            if nxt != n:
                matrix[i][index[nxt]] -= 1

    # Fraction-free Gaussian elimination.
    previous_pivot = 1
    for k in range(size - 1):
        pivot = matrix[k][k]
        for i in range(k + 1, size):
            factor = matrix[i][k]
            for j in range(k + 1, size + 1):
                matrix[i][j] = (
                    matrix[i][j] * pivot - factor * matrix[k][j]
                ) // previous_pivot
            matrix[i][k] = 0
        previous_pivot = pivot

    solution = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][size])
        for j in range(i + 1, size):
            value -= matrix[i][j] * solution[j]
        solution[i] = value / matrix[i][i]

    result = solution[index[0]]
    return [result.numerator, result.denominator]
